package com.jnapanam.sportszone.tournament.dto;import com.jnapanam.sportszone.tournament.model.*;import java.time.Instant;import java.util.UUID;public record FixtureResponse(UUID id,int roundNumber,int matchNumber,String homeTeam,String awayTeam,String facilityCode,Instant scheduledAt,Integer homeScore,Integer awayScore,String winner,FixtureStatus status){public static FixtureResponse from(TournamentFixture f){return new FixtureResponse(f.getId(),f.getRoundNumber(),f.getMatchNumber(),f.getHomeTeam().getName(),f.getAwayTeam()==null?null:f.getAwayTeam().getName(),f.getFacility()==null?null:f.getFacility().getCode(),f.getScheduledAt(),f.getHomeScore(),f.getAwayScore(),f.getWinner()==null?null:f.getWinner().getName(),f.getStatus());}}
